mujoco.mj_forward(_m2, _d2)
print(f"data.xpos      (body frame origin)  {_d2.xpos[_hid]}")
print(f"data.xipos     (body centre of mass){_d2.xipos[_hid]}")
print(f"data.site_xpos (the palm site)      {_d2.site_xpos[_sid2]}")
